 const MAX_LENGTH = 256;

 const NUM = "0|[1-9]\\d*";
 const PRERELEASE_ID = `(?:${NUM}|\\d*[a-zA-Z-][a-zA-Z0-9-]*)`;
+const PRERELEASE_LOOSE_ID = "(?:\\d+|\\d*[a-zA-Z-][a-zA-Z0-9-]*)";
 const PRERELEASE = `(?:-(${PRERELEASE_ID}(?:\\.${PRERELEASE_ID})*))`;
 const BUILD = "(?:\\+([a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*))";
 const FULLPLAIN = `v?(${NUM})\\.(${NUM})\\.(${NUM})${PRERELEASE}?${BUILD}?`;
 const XID = `${NUM}|x|X|\\*`;
@@ -14,11 +15,13 @@

 const FULL = new RegExp(`^${FULLPLAIN}$`);
 const COMPARATOR = new RegExp(`^${GTLT}\\s*(${FULLPLAIN})$|^$`);
 const HYPHENRANGE = new RegExp(`^\\s*(${XRANGEPLAIN})\\s+-\\s+(${XRANGEPLAIN})\\s*$`);
-const COMPARATORTRIM = new RegExp(`(\\s*)${GTLT}\\s*(${LONETILDE}|${XRANGEPLAIN})`, "g");
+const LOOSEPLAIN = `[v=\\s]*(\\d+)\\.(\\d+)\\.(\\d+)(?:-?(${PRERELEASE_LOOSE_ID}(?:\\.${PRERELEASE_LOOSE_ID})*))?${BUILD}?`;
+const COMPARATORTRIM = new RegExp(`(\\s*)${GTLT}\\s*(${LOOSEPLAIN}|${XRANGEPLAIN})`, "g");
 const TILDETRIM = new RegExp(`(\\s*)${LONETILDE}\\s+`, "g");
 const CARETTRIM = /(\s*)\^\s+/g;
+const BUILD_GLOBAL = new RegExp(BUILD, "g");
 const TILDE = new RegExp(`^${LONETILDE}${XRANGEPLAIN}$`);
 const CARET = new RegExp(`^\\^${XRANGEPLAIN}$`);
 const XRANGE = new RegExp(`^${GTLT}\\s*${XRANGEPLAIN}$`);
 const STAR = /(<|>)?=?\s*\*/;
@@ -139,8 +142,9 @@
 }

 function parseComparatorSet(range: string): ComparatorSet {
   const trimmed = range
+    .replace(BUILD_GLOBAL, "")
     .replace(HYPHENRANGE, hyphenReplace)
     .replace(COMPARATORTRIM, "$1$2$3")
     .replace(TILDETRIM, "$1~")
     .replace(CARETTRIM, "$1^");
@@ -242,8 +246,10 @@
 }

